const persons=[{id:'p1',name:'示例人物甲',alive:true,location:'郡府',office:'縣令'}];
function model(year=184,month=1){return createPhase4Model(year,month,persons);}
function act(m:Phase4Model,action:Parameters<typeof applyPhase4Action>[1]){return applyPhase4Action(m,action,persons);}
function world():GameState {const history:OpeningHistory={regions:[],surnames:[]};const facts=createOpeningFacts(23,184,history);return dispatch(null,{version:ENGINE_VERSION,commandId:'p4-world',expectedRevision:0,type:'StartGame',name:`${facts.surname}景初`,seed:23,facts}).state!;}
const unit=(id:string,commanderId:string,faction:string,order:'待命'|'進攻'|'防守'|'撤退'='待命'):WarUnit=>({id,faction,commanderId,commanderName:`將領${commanderId}`,location:'汝南渡口（示例）',strength:100,reserve:50,supply:4,morale:70,fatigue:0,terrain:'平原',wounded:0,killed:0,routed:0,order});
