 it('因果處理清單每個 ID 只出現一次',()=>{const causes=model().causes;expect(new Set(causes).size).toBe(causes.length);expect(causes).toContain('dong-zhuo-central-control');expect(causes).toContain('regional-arms-resistance');});
 it('A214 v106 新增 204 年孫翊遇害節點；保留事件帳並不回補過年存檔',()=>{const old=createPhase4Model(203,1,persons,'phase4-scenario-106'),prefix=structuredClone(old.eventLedger);const upgraded=upgradePhase4Content(old,PHASE4_CONTENT_VERSION),id='sun-quan-brother-sun-yi-killed-204';expect(upgraded.nodes.find(node=>node.contentId===id)?.status).toBe('pending');expect(upgraded.eventLedger).toEqual(prefix);const advanced=advancePhase4(upgraded,360);expect(advanced.nodes.find(node=>node.contentId===id)?.status).toBe('triggered');const event=advanced.eventLedger.find(item=>item.detail.includes('孫權之弟、丹楊太守翊遇害'));expect(event?.source).toContain('建安九年');expect(event?.source).toContain('依年序換算建安九年為公元 204 年');const late=upgradePhase4Content(createPhase4Model(204,1,persons,'phase4-scenario-106'),PHASE4_CONTENT_VERSION);expect(late.nodes.find(node=>node.contentId===id)).toMatchObject({status:'resolved',resolvedYear:204});expect(late.eventLedger.some(item=>item.detail.includes('孫權之弟、丹楊太守翊遇害'))).toBe(false);});
