 it('A222 v111 220 年存檔升至 v114 後觸發趙咨、孫登外交節點；已過年份不回補',()=>{const id='sun-quan-wei-envoys-and-sun-deng-investiture-221',old=createPhase4Model(220,1,persons,'phase4-scenario-111'),prefix=structuredClone(old.eventLedger),upgraded=upgradePhase4Content(old,PHASE4_CONTENT_VERSION);expect(upgraded.nodes.find(node=>node.contentId===id)?.status).toBe('pending');expect(upgraded.eventLedger).toEqual(prefix);const advanced=advancePhase4(upgraded,360);expect(advanced.nodes.find(node=>node.contentId===id)?.status).toBe('triggered');const event=advanced.eventLedger.find(item=>item.detail.includes('趙咨使魏'));expect(event?.source).toContain('沈珩');expect(event?.source).toContain('孫登');expect(answerKnownHistoricalEventQuestion('孫權在 221 年做了什麼？',world())?.answer).toContain('趙咨使魏、孫權辭魏封孫登而立為太子');const late=upgradePhase4Content(createPhase4Model(221,1,persons,'phase4-scenario-111'),PHASE4_CONTENT_VERSION);expect(late.nodes.find(node=>node.contentId===id)).toMatchObject({status:'resolved',resolvedYear:221});expect(late.eventLedger.some(item=>item.detail.includes('趙咨使魏'))).toBe(false);});
 it('A224 v112 224 年存檔升至 v114 後觸發孫邵、顧雍交接；已過年份不回補',()=>{const id='wu-chancellor-succession-225',old=createPhase4Model(224,1,persons,'phase4-scenario-112'),prefix=structuredClone(old.eventLedger),upgraded=upgradePhase4Content(old,PHASE4_CONTENT_VERSION);expect(upgraded.nodes.find(node=>node.contentId===id)?.status).toBe('pending');expect(upgraded.eventLedger.slice(0,prefix.length)).toEqual(prefix);const advanced=advancePhase4(upgraded,360);expect(advanced.nodes.find(node=>node.contentId===id)?.status).toBe('triggered');const event=advanced.eventLedger.find(item=>item.detail.includes('孫邵去世、顧雍繼任吳丞相'));expect(event?.source).toContain('黃武四年夏五月');expect(event?.source).toContain('六月以太常顧雍為丞相');expect(answerKnownHistoricalEventQuestion('西元 225 年發生了什麼事？',world())?.answer).toContain('孫邵去世、顧雍繼任吳丞相');const late=upgradePhase4Content(createPhase4Model(225,1,persons,'phase4-scenario-112'),PHASE4_CONTENT_VERSION);expect(late.nodes.find(node=>node.contentId===id)).toMatchObject({status:'resolved',resolvedYear:225});expect(late.eventLedger.slice(0,createPhase4Model(225,1,persons,'phase4-scenario-112').eventLedger.length)).toEqual(createPhase4Model(225,1,persons,'phase4-scenario-112').eventLedger);expect(late.eventLedger.some(item=>item.detail.includes('孫邵去世、顧雍繼任吳丞相'))).toBe(false);});
