 it('第六階段長局回歸：160年至280年可逐段推進並完整重播事件流',()=>{const history:OpeningHistory={regions:[],surnames:[]};const facts=createOpeningFacts(170,160,history);const start=dispatch(null,{version:ENGINE_VERSION,commandId:'phase6-century-start',expectedRevision:0,type:'StartGame',name:`${facts.surname}長局`,seed:170,facts});let state=start.state!;const events:GameEvent[]=[start.event!];for(let decade=1;decade<=12;decade++){const result=dispatch(state,{version:ENGINE_VERSION,commandId:`phase6-decade-${decade}`,expectedRevision:state.revision,worldlineId:state.worldlineId,type:'Phase4Action',action:{type:'AdvanceDays',days:3600}});state=result.state!;events.push(result.event!);}expect(state.phase4?.year).toBe(280);expect(state.character.age).toBe(120);for(const title of ['北海、東萊、琅邪冬寒記錄','黃巾起事','少帝與獻帝更替','董卓遇弒與李傕、郭汜攻陷長安','曹操再征徐州','張邈迎呂布與兗州戰事','獻帝車駕東歸與途中戰事','袁術僭號仲氏','獻帝遷都許縣','下邳之戰與呂布敗亡','官渡之戰','袁紹病卒與袁氏繼承','白狼山戰事與烏桓勢力轉折','袁譚敗亡與袁氏勢力轉折','鄴城陷落與袁氏河北局勢逆轉','袁譚袁尚爭冀州','孫權西征黃祖、破其舟軍','高幹敗走與壺關平定','孫權再征黃祖、擄其人民而還','赤壁交戰','潼關戰事與關中平定','雒城陷落與劉璋出降','合肥未克，孫權撤軍時遭張遼襲擊','曹操征定漢中、張魯出降','曹操進爵魏王','建安二十二年疫癘','宛城侯音起事','曹丕親征廣陵、臨江觀兵','諸葛亮南征、四郡平定','魏文帝去世、明帝曹叡即位','諸葛亮進屯漢中','孫權取荊州、關羽敗亡','漢魏禪代','劉備於成都即皇帝位','夷陵戰局逆轉','劉備崩於永安宮','諸葛亮首次北伐與街亭失利','孫權即皇帝位','諸葛亮病卒於渭濱','高平陵政局轉折','蜀漢降魏','魏晉禪代','孫吳降晉'])expect(state.phase4?.eventLedger.some(event=>event.detail.includes(title))).toBe(true);expect(state.phase4?.historicalPersons.find(person=>person.id==='sun-jian')?.alive).toBe(false);expect(replay(events)).toEqual(state);},20000);
 it('第六階段長局抵達三國終局後，可分支繼續人生或選結局且兩支都能重播',()=>{const history:OpeningHistory={regions:[],surnames:[]};const facts=createOpeningFacts(171,160,history);const start=dispatch(null,{version:ENGINE_VERSION,commandId:'phase6-ending-start',expectedRevision:0,type:'StartGame',name:`${facts.surname}終局`,seed:171,facts});let base=start.state!;const prefix:GameEvent[]=[start.event!];for(let decade=1;decade<=12;decade++){const result=dispatch(base,{version:ENGINE_VERSION,commandId:`phase6-ending-decade-${decade}`,expectedRevision:base.revision,worldlineId:base.worldlineId,type:'Phase4Action',action:{type:'AdvanceDays',days:3600}});base=result.state!;prefix.push(result.event!);}expect(base.phase4?.year).toBe(280);const chosenEvents=[...prefix];let chosen=dispatch(base,{version:ENGINE_VERSION,commandId:'phase6-end-unify',expectedRevision:base.revision,worldlineId:base.worldlineId,type:'Phase4Action',action:{type:'SetUnified',unified:true}});chosenEvents.push(chosen.event!);chosen=dispatch(chosen.state!,{version:ENGINE_VERSION,commandId:'phase6-end-choice',expectedRevision:chosen.state!.revision,worldlineId:base.worldlineId,type:'Phase4Action',action:{type:'ChooseEnding',ending:'歸隱故里'}});chosenEvents.push(chosen.event!);expect(chosen.state?.phase4).toMatchObject({ending:'chosen',chosenEnding:'歸隱故里'});expect(replay(chosenEvents)).toEqual(chosen.state);const continuedEvents=[...prefix];let continued=dispatch(base,{version:ENGINE_VERSION,commandId:'phase6-continue-unify',expectedRevision:base.revision,worldlineId:base.worldlineId,type:'Phase4Action',action:{type:'SetUnified',unified:true}});continuedEvents.push(continued.event!);continued=dispatch(continued.state!,{version:ENGINE_VERSION,commandId:'phase6-continue-life',expectedRevision:continued.state!.revision,worldlineId:base.worldlineId,type:'Phase4Action',action:{type:'ContinueAfterUnification'}});continuedEvents.push(continued.event!);continued=dispatch(continued.state!,{version:ENGINE_VERSION,commandId:'phase6-continue-year',expectedRevision:continued.state!.revision,worldlineId:base.worldlineId,type:'Phase4Action',action:{type:'AdvanceDays',days:360}});continuedEvents.push(continued.event!);expect(continued.state?.phase4?.year).toBe(281);expect(continued.state?.phase4?.ending).toBe('continuing');expect(replay(continuedEvents)).toEqual(continued.state);},20000);
 it('A23 跨年推進逐年處理事件與死亡硬節點；一般治療能力不會自動救人',()=>{const m=advancePhase4(model(),7*360+40);const death=m.nodes.find(n=>n.contentId==='sun-jian-death-191');expect(m.nodes.find(n=>n.contentId==='coalition-190')?.status).toBe('triggered');expect(death?.status).toBe('resolved');expect(m.historicalPersons.find(p=>p.id==='sun-jian')).toMatchObject({alive:false,deathYear:191});expect(m.eventLedger.filter(e=>e.type==='死亡硬節點落實')).toHaveLength(1);});
 it('A23 正常複選行動在死亡節點觸發當日中斷，未完成行動不結算且保留介入窗口',()=>{expect(MAX_TURNS).toBeGreaterThanOrEqual(85);let s=world();for(let i=0;i<83;i++){s=dispatch(s,{version:ENGINE_VERSION,commandId:`reachable-${i}`,expectedRevision:s.revision,worldlineId:s.worldlineId,type:'SubmitActionPlan',intents:['耕讀自持'],supplement:''}).state!;}s=dispatch(s,{version:ENGINE_VERSION,commandId:'approach-node',expectedRevision:s.revision,worldlineId:s.worldlineId,type:'Phase4Action',action:{type:'AdvanceDays',days:29}}).state!;const beforeMoney=s.character.money;const plan=dispatch(s,{version:ENGINE_VERSION,commandId:'reach-death-window',expectedRevision:s.revision,worldlineId:s.worldlineId,type:'SubmitActionPlan',intents:['耕讀自持'],supplement:''});expect(plan.event?.type).toBe('ActionPlanResolved');if(plan.event?.type!=='ActionPlanResolved'||plan.event.version!==ENGINE_VERSION)throw new Error('expected v5 action plan');expect(plan.event.payload.elapsedDays).toBe(1);expect(plan.event.payload.executedIntents).toEqual([]);expect(plan.event.payload.interruptedIntent).toBe('耕讀自持');expect(plan.state?.character.money).toBe(beforeMoney);expect(plan.state?.phase4?.nodes.find(n=>n.contentId==='sun-jian-death-191')?.status).toBe('triggered');expect(plan.state?.phase4?.historicalPersons.find(p=>p.id==='sun-jian')?.alive).toBe(true);});
 it('孫堅示例的 30 日是事件專屬工程設定；窗口內可救、期滿死亡且不再開窗',()=>{expect(ENGINEERING.deathInterventionWindowDaysByEvent['sun-jian-death-191']).toBe(30);let m=advancePhase4(model(),7*360);expect(m.nodes.find(n=>n.contentId==='sun-jian-death-191')?.status).toBe('triggered');m=advancePhase4(m,29);expect(m.historicalPersons.find(p=>p.id==='sun-jian')?.alive).toBe(true);m=advancePhase4(m,1);expect(m.historicalPersons.find(p=>p.id==='sun-jian')).toMatchObject({alive:false,deathYear:191});expect(m.nodes.find(n=>n.contentId==='sun-jian-death-191')?.status).toBe('resolved');expect(()=>act(m,{type:'InterveneDeath',nodeId:'sun-jian-death-191',personId:'sun-jian',method:'一般醫療',location:'長江中游（節點資料）'})).toThrow('沒有仍在個別死亡介入窗口內的存活人物');m=advancePhase4(m,100);expect(m.nodes.find(n=>n.contentId==='sun-jian-death-191')?.status).toBe('resolved');});
 it('各死亡事件可設定不同窗口；未設定窗口不繼承 30 日並於觸發日落實',()=>{const samples:HistoricalNodeContent[]=[{id:'test-death-five',kind:'death',title:'五日窗口人物',startYear:185,endYear:185,precision:'year',source:'測試用工程情境。',causes:[],carrier:'五日窗口人物',historicalPersonId:'test-five',description:'測試專用。'},{id:'test-death-two',kind:'death',title:'二日窗口人物',startYear:185,endYear:185,precision:'year',source:'測試用工程情境。',causes:[],carrier:'二日窗口人物',historicalPersonId:'test-two',description:'測試專用。'},{id:'test-death-none',kind:'death',title:'未設窗口人物',startYear:185,endYear:185,precision:'year',source:'測試用工程情境。',causes:[],carrier:'未設窗口人物',historicalPersonId:'test-none',description:'測試專用。'}];HISTORY_CONTENT.push(...samples);ENGINEERING.deathInterventionWindowDaysByEvent['test-death-five']=5;ENGINEERING.deathInterventionWindowDaysByEvent['test-death-two']=2;try{let m=model();m.historicalPersons.push(...[{id:'test-five',name:'五日窗口人物',alive:true,location:'示例地點',role:'測試人物',source:'測試'},{id:'test-two',name:'二日窗口人物',alive:true,location:'示例地點',role:'測試人物',source:'測試'},{id:'test-none',name:'未設窗口人物',alive:true,location:'示例地點',role:'測試人物',source:'測試'}]);m=advancePhase4(m,360);const status=(id:string)=>m.nodes.find(n=>n.contentId===id)?.status;expect(status('test-death-five')).toBe('triggered');expect(status('test-death-two')).toBe('triggered');expect(status('test-death-none')).toBe('resolved');expect(m.historicalPersons.find(p=>p.id==='test-none')?.alive).toBe(false);expect(()=>act(m,{type:'InterveneDeath',nodeId:'test-death-none',personId:'test-none',method:'一般醫療',location:'示例地點'})).toThrow('沒有仍在個別死亡介入窗口內的存活人物');expect(m.historicalPersons.find(p=>p.id==='test-five')?.alive).toBe(true);m=advancePhase4(m,2);expect(m.nodes.find(n=>n.contentId==='test-death-two')?.status).toBe('resolved');expect(m.historicalPersons.find(p=>p.id==='test-two')?.alive).toBe(false);expect(m.nodes.find(n=>n.contentId==='test-death-five')?.status).toBe('triggered');expect(m.historicalPersons.find(p=>p.id==='test-five')?.alive).toBe(true);m=advancePhase4(m,3);expect(m.nodes.find(n=>n.contentId==='test-death-five')?.status).toBe('resolved');expect(m.historicalPersons.find(p=>p.id==='test-five')?.alive).toBe(false);}finally{for(const sample of samples){const index=HISTORY_CONTENT.findIndex(item=>item.id===sample.id);if(index>=0)HISTORY_CONTENT.splice(index,1);delete ENGINEERING.deathInterventionWindowDaysByEvent[sample.id];}}});
 it('A24 直接、充分且成功的節點介入可打破死亡硬節點；同一節點不補殺',()=>{let m=advancePhase4(model(),6*360);m=advancePhase4(m,360);const node=m.nodes.find(n=>n.contentId==='sun-jian-death-191')!;expect(node.status).toBe('triggered');expect(()=>act(m,{type:'InterveneDeath',nodeId:node.contentId,personId:'sun-jian',method:'一般醫療',location:'家宅・庭院'})).toThrow('死亡介入窗口');m={...m,playerLocation:'長江中游（節點資料）'};m=act(m,{type:'InterveneDeath',nodeId:node.contentId,personId:'sun-jian',method:'一般醫療',location:'長江中游（節點資料）'});expect(m.nodes.find(n=>n.contentId===node.contentId)?.status).toBe('broken');m=advancePhase4(m,400);expect(m.historicalPersons.find(p=>p.id==='sun-jian')?.alive).toBe(true);expect(m.eventLedger.filter(e=>e.type==='死亡硬節點落實')).toHaveLength(0);});
 it('一般醫療缺少物資便不能宣稱救治成功，也不能改變死亡節點',()=>{let m=advancePhase4(model(),7*360);m={...m,playerLocation:'長江中游（節點資料）',medicalSupplies:0};expect(()=>act(m,{type:'InterveneDeath',nodeId:'sun-jian-death-191',personId:'sun-jian',method:'一般醫療',location:'長江中游（節點資料）'})).toThrow('缺少足夠救治資源');expect(m.nodes.find(n=>n.contentId==='sun-jian-death-191')?.status).toBe('triggered');expect(m.medicalSupplies).toBe(0);});
