 it('A145 戰場物件、條件鏈與視線以示例資料保存；未知引用遭拒且不自行結算',()=>{const scene:BattleSceneManifest={example:true,objects:[{id:'frame',label:'弩臺',location:'北岸土坡',condition:'支架穩固'},{id:'rope',label:'牽繫木索',location:'弩臺與拒馬間',condition:'繃緊'},{id:'obstacle',label:'拒馬',location:'守軍前沿',condition:'木樁固定'}],potentialChains:[{id:'frame-rope',fromObjectId:'frame',toObjectId:'rope',triggerCondition:'弩臺側架受擊斷裂',possibleEffect:'木索可能鬆脫，尚未結算',affectedUnitIds:['u1']}],observers:[{id:'front',side:'前列',location:'拒馬後方',visibility:'能見前沿，後陣受煙塵遮擋'}]};expect(()=>act(model(),{type:'StartBattle',id:'bad-scene',location:'渡口',units:[unit('u1','a','甲')],protagonistPresent:false,scene:{...scene,potentialChains:[{...scene.potentialChains[0],toObjectId:'missing'}]}})).toThrow('戰場潛在因果鏈無效');const started=act(model(),{type:'StartBattle',id:'scene-battle',location:'渡口前線（示例）',units:[unit('u1','a','甲'),unit('u2','b','乙')],protagonistPresent:true,scene});expect(started.battle?.scene).toEqual(scene);expect(started.battle?.units.every(entry=>entry.killed===0&&entry.wounded===0)).toBe(true);const advanced=act(started,{type:'BattleRound',orders:{u1:'防守',u2:'防守'}});expect(advanced.battle?.scene).toEqual(scene);expect(advanced.battle?.logs.some(log=>log.includes('弩臺已塌'))).toBe(false);});
